\SetKwFunction{FTerminalUpdatae}{Edge-Connectivity-One-Level-Update}

\begin{lemma}[\cite{js20}]\label{lem:old_main_initialization}
Given a graph $G$, two integers $c$ and $\gamma$ such that $\gamma > c$, and a conductance parameter $0 < \phi < 1$, 
there is an algorithm \FTerminalInitialization to initialize a one-level terminal edge connectivity data structure $(G, \calP, CC, F)$ with parameters $c, \phi$ and $\gamma$ in time $m^{1+o(1)} \cdot c^{O(c)} / \mathrm{poly}(\phi)$ such that $\sparsifier_{c, \gamma}(G, \calP, CC, F)$ contains at most \[m \cdot \phi \cdot \factor\] vertices and edges. 
\end{lemma}

\begin{lemma}[\cite{js20}]\label{lem:old_main}
Given a one-level terminal edge connectivity data structure $(G, \calP, CC, F)$ with parameters $c^2 + 2c, \phi$ and $\gamma$ satisfying $\gamma > c^2 + 2c$, and an update sequence $\updateseq$ of $G$ which contains vertex/edge insertions/deletions, 
Algorithm 
\FTerminalUpdatae with running time $O(|\updateseq|)\cdot O(c/\phi)^{O(c^2)}$ updates the data structure to $(G', \calP', CC', F')$ with parameters $c, \phi/2^{O(\log^{1/3}n\log\log n)}$ and $\gamma$, and outputs an update sequence $\updateseq'$ and a vertex set $S$ satisfying the following properties:
\begin{enumerate}
        \item $G'$ is the resulted graph of applying $\updateseq$ to $G$.
    \item $\calP'$ is a $\phi/2^{O(\log^{1/3}n\log\log n)}$-expander decomposition of $G'$. Furthermore, each cluster $P'\in\mathcal P'$ either contains only a single vertex or is a subset of a cluster $P\in \mathcal P$ such that $G'[P'] = G[P']$.
    \item $CC'$ is a $c$-cut containment set for $G'$ and $\calP'$. 
    \item $F'$ is an unweighted spanning forest of $G'\setminus CC'$.     
    \item The sparsifier maintained in the data structure is $\sparsifier_{c, \gamma}(G', \calP', CC', F')$.
    \item $\updateseq'$ updates $\sparsifier_{c^2 + 2c, \gamma}(G, \calP, CC, F)$ to $\sparsifier_{c, \gamma}(G', \calP', CC', F')$. The length of $\updateseq'$ is at most $\abs{\updateseq}(10c)^{O(c)}$.
    \item $S = (\endpoints(\partial_G(\calP)) \setminus \endpoints(\partial_{G'}(\calP'))) \cup (\endpoints(\partial_{G'}(\calP')) \setminus \endpoints(\partial_G(\calP)))$ such that $|S| = O(|\updateseq|)$.
\end{enumerate}
\end{lemma}

A multi-level terminal edge connectivity data structure with parameters $c, \phi$, and  $\gamma$
is a set of one-level data structures $\set{(G^{(i)}, \mathcal P^{(i)}, CC^{(i)}, F^{(i)})}_{i=0}^\ell$ satisfying the following conditions:
\begin{enumerate}
    \item[(c1)] $(G^{(i)}, \calP^{(i)}, CC^{(i)}, F^{(i)})$ is a one-level terminal edge connectivity data structure with parameters $c, \phi$  and $\gamma$.     \item[(c2)]  $G^{(0)}$ is the input graph, and $G^{(i)} = \sparsifier_{c, \gamma} (G^{(i-1)}, \mathcal P^{(i-1)}, CC^{(i-1)}, F^{(i)})$ for each $0 < i \leq \ell$.
    \item[(c3)] $\calP^{(\ell)}$ contains only one cluster.
\end{enumerate}

\begin{Definition}\label{def:aux-graph}
 For a graph $G = (V, E)$ and a partition $\mathcal P$ of $V$,
 the auxiliary graph of $G$ with respect to $\mathcal P$, denoted as $G_*$,  is obtained from $G$ as follows: 
 For each $P\in\mathcal P$, add a special terminal vertex $t_P$ and connect $t_P$ to every terminal vertex in $P$. 

 The auxiliary partition $\calP_*$ is defined as  $\{P_* | P\in \mathcal P\}$, where $P_* = P\cup \set {t_P}$. 
The terminals of $G_*$ with respect to $\calP_*$ are the terminals of $G$ with respect to $\calP$ union all the special terminals.
 \end{Definition}

\begin{Definition}\label{def:local_cut}
Let $G = (V, E)$ be a graph with $T$ as terminals, and $\alpha, c$ be two positive integers. We say a cut $C = (U, V\cut U)$ is an $(\alpha, c)$-local cut in $G$ with respect to $T$ if all of the following conditions hold
\begin{itemize}
    \item The size of cut $C$ is at most $c$;
    \item Either $U$ or $V\cut U$ has volume at most $\alpha$ in $G$;
    \item $T\subset U$ or $T\subset V\cut U$.
\end{itemize}
A cut $C$ is a minimum $(\alpha, c)$-local cut in $G$ with respect to $T$ if $C$ is a $(\alpha, c)$-local cut in $G$ with respect to $T$ and there is no other $(\alpha, c)$-local cuts in $G$ with respect to $T$ with the size smaller than $C$.
\end{Definition}

\begin{Definition}[One-level Sparsifier]\label{def:lambda}
 Given parameters $c, \phi$, $c'\geq c$, $\gamma\geq c'$,  and $\alpha\geq \ceil{c/\phi}$, a one-level global minimum cut data structure w.r.t. these parameters consists of two parts:
\begin{enumerate}
    \item[(1)] A one-level terminal edge connectivity data structure  $\sparsifier_{c', \gamma}(G, \calP, CC, F)$ (Section \ref{sec:js20_review}), which contains the input graph $G = (V, E)$, a vertex partition $\calP$ of $G$ given by a $\phi$-expander decomposition, and a $c'$-cut containment set $CC$ with respect to $G$ and $\calP$.
    \item[(2)] Assuming $G_*$ is the auxiliary graph of $G$ with respect to $\mathcal P$, a priority queue $\Lambda_{G_*}$ that contains all vertex sets $U$ such that
    \begin{itemize}
    \item There exists a $P\in\mathcal P$ such that $U\subset P_*$, where $P_*$ is the corresponding cluster of $P$ in $G_*$
    \item $U$ induces a connected subgraph in $G_*$
    \item  $(U, P_*\cut U)$ is a $(3\alpha, c)$-local cut in $G_*[P_*]$. The terminal set is $(\endpoints(\partial_G(\mathcal P))\cap P) \cup\set{t_P}$.
        \end{itemize}
The elements in $\Lambda_{G_*}$ are ordered by the size of each cut $(U, P_*\cut U)$.
\end{enumerate}
\end{Definition}

 \begin{lemma}\label{lem:one-level-query}
Let $\sparsifier_{c', \gamma}(G, \mathcal P, CC, F)$ be a one-level terminal edge connectivity sparsifier data structure with parameters $c'$, $\gamma$ such that $c'\geq c$ and $\gamma \geq c'$. 
Let $\Lambda_{G_*}$ be the priority queue defined in Definition \ref{def:lambda}.
Let $C_1$ be the cut in $G$ induced by the cut-set of a minimum $c$-cut in $\sparsifier_{c', \gamma}(G, \mathcal P, CC, F)$ (if one such cut exists in $\sparsifier_{c', \gamma}(G, \mathcal P, CC, F)$); otherwise $C_1 = \perp$.

Let $U_2$ be a vertex set in $\Lambda_{G_*}$ with highest priority. If $U_2$ exists, let $P_*$ be the cluster in $G_*$ that contains $U_2$ and $P$ be the cluster in $\mathcal P$ corresponding to $P_*$. We use $C_2$ to denote cut $(U_2\cap V, V_*\cut U_2\cap V)$. If $U_2$ does not exist, $C_2 = \perp$.

If $ C_1$ and $C_2$ are both $\perp$, then $G$ does not have a $c$-cut. Otherwise, the smaller one between $ C_1$ and $C_2$ is a minimum $c$-cut of $G$.
\end{lemma}

A multi-level global minimum cut data structure 
    $$\set{(G^{(j)}, \mathcal P^{(j)}, CC^{(j)}, F^{(j)},\Lambda_{G_*^{(j)}}) }_{j=1}^{\ell}$$
 contains a set of $\ell$ one-level  global minimum cut data structures such that conditions (c1), (c2) and (c3) hold.

