\begin{algorithm}[htb]
\caption{Cut Enumeration}\label{alg:enum-new}
\KwIn{$G_*=(V_*, E_*)$\newline $v$: a vertex in $G_*$, \newline $ \alpha, c$: positive integers}
\KwOut{$\mathcal{C}$: a list of subsets of $V_*$} 
\SetKwFunction{FLocalEnum}{Enumerate-Cuts}
\SetKwFunction{FLocal}{Minimum-Local-Cut}
\SetKwFunction{FCutRecursive}{Cut-Enumeration-Recursive}
\SetKwFunction{FCutVerify}{Atomic-Cut-Verification}
\SetKwProg{Fn}{Function}{:}{}
\Fn{\FLocalEnum{$G_*, v, \alpha, c$}} {
    $T_{\mathcal P}\gets$ the set of special terminals added when constructing $G_*$, as per Definition \ref{def:aux-graph}\;
        $\mathcal{C} \gets \emptyset$\;
    \FCutRecursive($G_*, v, \alpha, c, \emptyset, \mathcal{C}$)\;
    \Return $\mathcal{C}$
}
\Fn{\FCutRecursive{$G_*, v, \alpha, c, F,  \mathcal{C}, T_{\mathcal P}$}} {
    \lIf{$c < 0$} {\Return}
    Run a DFS from $v$ in $G_*$ until the DFS stops or $\vol_{G}(U) > 3\alpha$, where $U$ is the set of visited vertices\label{alg:new-enum:line7}\; 
            \If{    $F$ is exactly the set of edges between $U$ and $V\cut U$ in $G_*$, $\sum_{(u, w, \beta)\in F}\beta \leq c$, and $\vol_{G}(U)+ \sum_{(u, w, \beta)\in F}\beta\leq 3\alpha$} {\label{alg:new-enum:line8}
                $\mathcal{C} \gets \mathcal{C} \cup \{U\}$\;
        \Return    }

    \For{every edge $(u, w, \beta)$ of $G_*$ such that $u, w\in U$ and $u,v\not\in T_{\mathcal P}$}{\label{alg:new-enum:line12}
        $F \gets F\cup \set{(u, w, \beta)}$\;
        Remove edge $(u, w, \beta)$ from $G[\mathcal P]$\;
            \FCutRecursive{$G_*,  v, \alpha,c-\beta,  F,  \mathcal{C}$}\;
        Add edge $(u, w, \beta)$ back to $G[\mathcal P]$\;
    }
}
\end{algorithm}

