\begin{algorithm}[htb]
\SetKw{Continue}{continue}
\caption{One-level Minimum Cut Data Structure Initialization}\label{alg:one-level-init-new}
\KwIn{$G$: a graph,\newline 
$c, \phi, c', \gamma, \alpha$: parameters.
}

\SetKwProg{Fn}{Function}{:}{}

\Fn{\Fdeltainit}{
$(G,\mathcal P, CC, F)\gets \FTerminalInitialization(G, c', \phi, \gamma)$\;
\For{all $P\in\mathcal P$} {\label{alg:one-init-new-line4}
    Add vertex $t_P$ to $G$\;
    \For {each $t\in \endpoints(\partial_G(\mathcal P))\cap P$} {
        Add edge $(t_P, t)$ to $G$ \label{alg:one-init-new-line7}\; 
    }
}
$G_* = (V_*, E_*)\gets$ the resulting graph\;
    \For{all $v\in V_*$}{
        $\mathcal C\gets\texttt{Enumerate-Cuts}(G_*, v, \alpha, c)$\label{alg:one-init-new-line6}\;
        \For{$U\in \mathcal C$}{
                            Insert $U$ into $\Lambda_{G_*}$ with priority $\abs{\partial_{G_*}(U)}$\hfill\tcp{$\abs{\partial_{G_*}(U)}$ can be computed and returned by \texttt{Enumerate-Cuts}. We do not need to find all edges in the cut-set here}
                    }

                            }


\Return $(G,\mathcal P, CC, F,  \Lambda_{G_*})$\;
}
