\begin{algorithm}[htb!]
\caption{Update One Level Minimum Cut Data Structure}\label{alg:one-up-new}
\KwIn{
$(G, \mathcal P, CC, F, \Lambda_{G_*})$: one-level minimum cut data structure, w.r.t. parameters $c, \phi, c', \gamma, \alpha$ \newline
$\updateseq$: update sequence for multigraph $G$
}
\KwOut{
$(G', \mathcal P', CC', F',\Lambda_{G'_*})$: one-level minimum cut data structure for the up-to-date graph,  w.r.t parameters $c, \phi/\factor, c, \gamma, \alpha$ \newline
$\updateseq'$: update sequence that should be applied to the next sparsifier}
\SetKwFunction{Fenuupdate}{Update-Enumeration}
