\Fn{\Fdeltaupdate}
{
    $(G', \calP', CC', F'), \updateseq', S\gets $ \FTerminalUpdatae{$(G, \calP, CC, T), \updateseq, c', \phi, \gamma$}\;
            Add all vertices involved in $\updateseq$ to $S$\;\label{alg:one-up-new:line5}
    \tcp{Update $G_*$}

    \For{all $P'\in\mathcal P'$ such that $P'\cap S\neq \emptyset$} {\label{alg:one-up-new:line4}
