                                                $\mathcal C\gets $\texttt{Enumerate-Cuts}$(G'_*, v, \alpha, c )$\label{alg:one-up-new:line18-2}\;
        \For{each $U\in\mathcal C$} {\label{alg:one-up-new:line21}
            $j\gets $ the size of $(U, V\cut U)$\;
                                    Insert $U$ into $\Lambda_{G_*}$ with priority $j$\label{alg:one-up-new:line26}
        }
    }
        Change the name of  $\Lambda_{G_*}$ to $\Lambda_{G_*'}$

    \Return $(G', \mathcal P', CC', F',\Lambda_{G_*'})$, $\updateseq'$
}
